const columns = [];
const columns_quick_select = _.cloneDeep(event.data.columns_quick_select);
_.forEach(columns_quick_select, function (field) {
  const column_field = _.find(event.data.columns, { field });
  if (column_field) {
    columns.push(column_field)
  } else {
    columns.push({
      field
    })
  }
});
doAction({
  "componentId": "form_object_listviews",
  "actionType": "setValue",
  "args": {
    "value": {
      columns
    }
  }
});

const mobile_columns = [];
const columns_quick_select = _.cloneDeep(event.data.columns_quick_select);
_.forEach(columns_quick_select, function (field) {
  const column_field = _.find(event.data.mobile_columns, { field });
  if (column_field) {
    mobile_columns.push(column_field)
  } else {
    mobile_columns.push({
      field
    })
  }
});
doAction({
  "componentId": "form_object_listviews",
  "actionType": "setValue",
  "args": {
    "value": {
      mobile_columns
    }
  }
});

body.initApiAdaptor:
var data;
if (recordId) {
  data = payload.data || { _filters_type_controller: 'conditions' };
  //数据格式转换
  if (data) {
    data.sort = lodash.map(data.sort, (item) => {
      return item.field_name + ":" + item.order;
    });
    data.searchable_fields = lodash.map(data.searchable_fields, 'field');

    if (data.filters && lodash.isString(data.filters)) {
      try {
        data.filters = JSON.parse(data.filters);
      } catch (e) { }
    }

    if (data.filters && lodash.isString(data.filters)) {
      data._filters_type_controller = 'function';
    } else {
      data._filters_type_controller = 'conditions'
    }

    if (data._filters_type_controller === 'conditions') {
      data._filters_conditions = window.amisConvert.filtersToConditions(data.filters || []);
    } else {
      data._filters_function = data.filters;
    }
  }
} else {
 const uiSchema = api.body.uiSchema;
 const contextDefaultData = context && context.data && context.data.defaultData; const defaultData = api.body.defaultData || contextDefaultData;
  let defaultValues = {};
 _.each(uiSchema && uiSchema.fields, function (field) {
    var value = SteedosUI.getFieldDefaultValue(field, api.body.global);
    if (!_.isNil(value)) {
      defaultValues[field.name] = value;
    }
  });
 if (defaultData && _.isObject(defaultData) && !_.isArray(defaultData)) {
    data = Object.assign({}, defaultValues, defaultData); 
  }else{data = Object.assign({}, defaultValues) } 
}
for (key in data) {
  if (data[key] === null) {
    delete data[key];
  }
}
payload.data = data;
delete payload.extensions; if (data.is_enable != false) { data.is_enable = true; };
return payload;

body.apiRequestAdaptor:
delete formData.created;
delete formData.created_by;
delete formData.modified;
delete formData.modified_by;
delete formData._display;

//数据格式转换
formData.sort = lodash.map(formData.sort, (item) => {
  const arr = item.split(':');
  return { field_name: arr[0], order: arr[1] };
});

formData.searchable_fields = lodash.map(formData.searchable_fields, (item) => {
  return { field: item };
});

if (!formData._filters_type_controller) {
  formData._filters_type_controller = 'conditions';
}

if (formData._filters_type_controller === 'conditions' && formData._filters_conditions) {
  formData.filters = window.amisConvert.conditionsToFilters(formData._filters_conditions);
  // formData.filters = JSON.stringify(window.amisConvert.conditionsToFilters(formData._filters_conditions), null, 4);
} else {
  formData.filters = formData._filters_function || null;
}

delete formData._filters_type_controller;
delete formData._filters_conditions;
delete formData._filters_function;

formData.crud_mode = formData.type === 'cards' ? 'cards' : 'table';

query = `mutation{record: object_listviews__insert(doc: {__saveData}){_id}}`;
if (formData.recordId) {
  query = `mutation{record: object_listviews__update(id: "` + api.body.recordId + `", doc: {__saveData}){_id}}`;
};
__saveData = JSON.stringify(JSON.stringify(formData));

api.data = { query: query.replace('{__saveData}', __saveData) };
return api;

actions.script:
/**
 * 校验失败时自动跳转的智能脚本 (包含当前 Tab 判断)
 */

// 1. 获取 Form 组件和存储
const formComponent = event.context.scoped.getComponentById('form_object_listviews');
if (!formComponent) {
  console.error('未找到 Form 组件，请检查 ID: form_object_listviews');
  return;
}

const fs = formComponent.props.store;
const errors = fs.errors;

if (!errors || Object.keys(errors).length === 0) {
  return;
}

const errorFields = Object.keys(errors);
let targetTabIndex = -1;

// 2. 获取 Tabs 组件实例
// 注意：这里使用了您提供的 SteedosUI 辅助方法来获取 tabsComponent
const tabsComponent = SteedosUI.getClosestAmisComponentByType(formComponent.context, "tabs")

if (!tabsComponent) {
  console.error('未找到 Tabs 组件');
  return;
}

const tabs = tabsComponent.props.tabs;

// 3. 遍历 Tabs 配置，查找第一个包含失败字段的 Tab 索引
for (let i = 0; i < tabs.length; i++) {
  const tabBodyItems = Array.isArray(tabs[i].body) ? tabs[i].body : [];
  for (const item of tabBodyItems) {
    if (item.name && errorFields.includes(item.name)) {
      targetTabIndex = i;
      break;
    }
  }

  if (targetTabIndex !== -1) {
    break;
  }
}

// 4. 执行跳转操作，并检查是否已在目标 Tab
if (targetTabIndex !== -1) {
  if (tabsComponent.switchTo) {
    // 关键优化：检查当前 Tab 索引
    // 注意：tabsComponent.currentIndex() 必须是 Tabs 组件实例提供的方法
    const currentTabIndex = tabsComponent.currentIndex();

    if (currentTabIndex !== targetTabIndex) {
      // 只有当目标 Tab 索引与当前索引不同时才执行跳转
      tabsComponent.switchTo(targetTabIndex);
      console.log(`校验失败字段 ${errorFields[0]} 自动跳转到 Tab 索引: ${targetTabIndex} (${tabs[targetTabIndex].title})`);
    } else {
      console.log(`校验失败字段 ${errorFields[0]} 位于当前 Tab (${targetTabIndex})，无需跳转。`);
    }
  } else {
    console.warn('Tabs 组件实例缺少 switchTo 方法。');
  }
} else {
  console.log('校验失败字段不在已知的任何 Tab 页签中。');
}
